-- University of Ghana Level 100 fees, part 4: Bachelor of Education programmes (College of Education schedule, 2026/27 provisional, GHS). Safe to run twice.
-- Rule from the owner: a Bachelor of Education whose name has Science in it uses the College of Education Science column; one with Arts in it uses the Arts column. Others are left blank.
do $$ begin
update public.programs p set fees_ghs=3462, internal_note=trim(coalesce(p.internal_note,'')||' UG fee schedule 2026/27 (provisional), College of Education, Bachelor of Science column, Level 100: GHS 3,462.') from public.schools s where s.id=p.school_id and s.name='University of Ghana' and p.name='Bachelor of Education in Computer Science' and p.mode='Regular' and p.campus is null and p.fees_ghs is null;
update public.programs p set fees_ghs=7405, internal_note=trim(coalesce(p.internal_note,'')||' UG fee schedule 2026/27 (provisional), College of Education, Bachelor of Science column, Level 100: GHS 7,405.') from public.schools s where s.id=p.school_id and s.name='University of Ghana' and p.name='Bachelor of Education in Computer Science' and p.mode='Fee-paying' and p.campus is null and p.fees_ghs is null;
