update public.programs p set fees_ghs=7405, internal_note=trim(coalesce(p.internal_note,'')||' UG fee schedule 2026/27 (provisional), College of Education, Bachelor of Science column, Level 100: GHS 7,405.') from public.schools s where s.id=p.school_id and s.name='University of Ghana' and p.name='Bachelor of Education in Science (Physics)' and p.mode='Fee-paying' and p.campus is null and p.fees_ghs is null;
update public.programs p set fees_ghs=3462, internal_note=trim(coalesce(p.internal_note,'')||' UG fee schedule 2026/27 (provisional), College of Education, Bachelor of Science column, Level 100: GHS 3,462.') from public.schools s where s.id=p.school_id and s.name='University of Ghana' and p.name='Bachelor of Education in Consumer Sciences' and p.mode='Regular' and p.campus is null and p.fees_ghs is null;
